export default function BookingPage() {
  const { providerId } = useParams<{ providerId: string }>();
  const [searchParams] = useSearchParams();
  const preselectedServiceId = searchParams.get('service') || '';

const [step, setStep] = useState<BookingStep>(preselectedServiceId ? 'staff' : 'service');
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedStaff, setSelectedStaff] = useState<Staff | null>(null);
  const [selectedSlot, setSelectedSlot] = useState<TimeSlot | null>(null);
  const [selectedAddons, setSelectedAddons] = useState<Addon[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(() => {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  });
  const [createdBooking, setCreatedBooking] = useState<BookingResponse | null>(null);
  const [couponCode, setCouponCode] = useState('');
  const [couponResult, setCouponResult] = useState<{ valid: boolean; discountType: string; discountValue: number; discountAmount: number; finalPrice: number; message?: string } | null>(null);
  const [couponLoading, setCouponLoading] = useState(false);

const { data: servicesRes } = useQuery({
    queryKey: ['services', providerId],
    queryFn: () => publicApi.services.listByProvider(providerId!),
    enabled: !!providerId,
  });

const { data: staffRes } = useQuery({
    queryKey: ['staff', providerId],
    queryFn: () => publicApi.staff.listByProvider(providerId!),
    enabled: !!providerId,
  });

const { data: slotsRes, isLoading: slotsLoading } = useQuery({
    queryKey: ['slots', providerId, selectedService?.id, selectedStaff?.id, selectedDate],
    queryFn: () =>
      publicApi.availability.getSlots(
        providerId!,
        selectedService!.id,
        selectedStaff!.id,
        selectedDate ?? new Date().toISOString().split('T')[0],
      ),
    enabled: !!providerId && !!selectedService?.id && !!selectedStaff?.id && !!selectedDate,
  });

const [pin, setPin] = useState('');
  const [pinMsg, setPinMsg] = useState<string | null>(null);
  const verifyPinMut = useMutation({
    mutationFn: () => publicApi.bookings.verifyPin(createdBooking!.id, pin),
    onSuccess: () => setPinMsg('PIN terverifikasi, booking dikonfirmasi!'),
    onError: (e) => setPinMsg(e instanceof Error ? e.message : 'PIN salah'),
  });

// Bundle B: reschedule + policy
  const [rescheduleDate, setRescheduleDate] = useState('');
  const [rescheduleTime, setRescheduleTime] = useState('09:00');
  const [rescheduleMsg, setRescheduleMsg] = useState<string | null>(null);
  const { data: policiesRes } = useQuery({
    queryKey: ['policies-public-booking'],
    queryFn: () => publicApi.policies.listPublic().then((r) => r.data),
  });
  const policyText = (policiesRes as unknown as { data?: { body?: string }[] })?.data?.[0]?.body || (policiesRes as unknown as { body?: string }[] | undefined)?.[0]?.body || 'Pembatalan sebelum 24 jam = refund penuh. Setelah itu no refund. Reschedule gratis 1x (409 jika melebihi).';
  const rescheduleMut = useMutation({
    mutationFn: () => {
      const version = (createdBooking as unknown as { version?: number })?.version ?? 1;
      const newStartsAt = new Date(`${rescheduleDate}T${rescheduleTime}:00+07:00`).toISOString();
      const newEndsAt = new Date(new Date(newStartsAt).getTime() + (selectedService?.duration ?? 60) * 60000).toISOString();
      return publicApi.bookings.reschedule(createdBooking!.id, { newStartsAt, newEndsAt, expectedVersion: version });
    },
    onSuccess: (res) => {
      setCreatedBooking(res.data as unknown as BookingResponse);
      setRescheduleMsg('Reschedule berhasil! Slot baru terkonfirmasi.');
    },
    onError: (e: unknown) => {
      const msg = e instanceof Error ? e.message : 'Reschedule gagal';
      // 409 is thrown as Error with message from ApiResponse
      setRescheduleMsg(msg.includes('409') || msg.includes('limit') ? 'Gagal: Batas reschedule gratis tercapai (409).' : msg);
    },
  });
  const calendarMut = useMutation({
    mutationFn: () => publicApi.bookings.calendarLink(createdBooking!.id),
  });

const createBooking = useMutation({
    mutationFn: (data: z.infer<typeof contactSchema>) =>
      publicApi.bookings.create({
        providerId: providerId!,
        serviceId: selectedService!.id,
        startsAt: selectedSlot!.startTime,
        endsAt: selectedSlot!.endTime,
        ...data,
        notes: data.notes || '',
        idempotencyKey: crypto.randomUUID(),
      }),
  });

const createPaymentIntent = useMutation({
    mutationFn: (bookingId: string) => publicApi.bookings.createPaymentIntent(bookingId, 'midtrans'),
  });

const services = servicesRes?.data ?? [];

useEffect(() => {
    if (preselectedServiceId && !selectedService && services.length > 0) {
      const match = services.find((s) => s.id === preselectedServiceId);
      if (match) setSelectedService(match);
    }
  }, [preselectedServiceId, services, selectedService]);
  const staffList = staffRes?.data ?? [];
  const slots = slotsRes?.data ?? [];

const filteredStaff = useMemo(() => {
    if (!selectedService) return staffList;
    return staffList.filter(
      (s) =>
        selectedService.id &&
        (!(s.specialties?.length) || s.specialties.includes(selectedService.category)),
    );
  }, [staffList, selectedService]);

const contactForm = useForm<ContactFormData>({
    resolver: zodResolver(contactSchema),
  });

