const loginSchema = z.object({
  email: z.string().email('Email tidak valid'),
  password: z.string().min(6, 'Password harus minimal 6 karakter'),
});

const otpSchema = z.object({
  email: z.string().email('Email tidak valid'),
  code: z.string().length(6, 'Kode OTP harus 6 digit'),
});

